tool.command:
## prepare the annotation databases
#if $annotation.hmm_cond.hmm_selector == 'mito_only'
    ln -s '$annotation.hmm_cond.annotation_hmm_mito' mito.fam &&
    hmmpress mito.fam &&
#elif $annotation.hmm_cond.hmm_selector == 'plastid_only'
    ln -s '$annotation.hmm_cond.annotation_hmm_plastid' plastid.fam &&
    hmmpress plastid.fam &&
#else
    ln -s '$annotation.hmm_cond.annotation_hmm_mito' mito.fam &&
    hmmpress mito.fam &&
    ln -s '$annotation.hmm_cond.annotation_hmm_plastid' plastid.fam &&
    hmmpress plastid.fam &&
#end if

oatk
-t "\${GALAXY_SLOTS:-2}"
#if $annotation.hmm_cond.hmm_selector == 'mito_only'
  -m mito.fam
#elif $annotation.hmm_cond.hmm_selector == 'plastid_only'
  -p plastid.fam
#else
-m mito.fam
-p plastid.fam
#end if
${syncasm.use_graph_mode}
-k ${syncasm.kmer_size}
-c ${syncasm.min_kmer_coverage}
-o oatk.asm
-s ${syncasm.smer_size}
-a ${syncasm.min_arc_coverage}
-D '${syncasm.max_data_usage}'
--max-bubble ${syncasm.max_bubble_size}
--max-tip ${syncasm.max_tip_size}
--weak-cross ${syncasm.weak_crosslink}
--unzip-round ${syncasm.unzip_rounds}
${syncasm.disable_read_ec}
-b ${annotation.batch_size}
-f ${pathfinder.prefer_circular_path}
-S ${pathfinder.min_annotation_score}
-e ${pathfinder.max_evalue}
-g '${pathfinder.min_core_gene_gain}'
-l ${pathfinder.min_seq_length}
-q ${pathfinder.min_seq_coverage}
-C ${pathfinder.max_copy_number}
${pathfinder.include_trna}
${pathfinder.include_rrna}
${pathfinder.disable_graph_clean}
--edge-c-tag '${tagging.edge_coverage_tag}'
--kmer-c-tag '${tagging.kmer_coverage_tag}'
--seq-c-tag '${tagging.seq_coverage_tag}'
'${input_reads}'
